#[track_caller]
fn failure(reason: SourceInferenceError) -> NatDefinitionElabError {
    if matches!(&reason, SourceInferenceError::ResourceLimit) {
        eprintln!("WF_RESOURCE_ORIGIN {}", std::panic::Location::caller());
        eprintln!("WF_RESOURCE_BACKTRACE {}", std::backtrace::Backtrace::force_capture());
    }
    NatDefinitionElabError::Inference(reason)
}

